<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #090d16;
        --panel: #121827;
        --panel-strong: #192235;
        --text: #f5f7fb;
        --muted: #b8c0cf;
        --line: #2a3447;
        --accent: #7c9cff;
        --danger: #ff5f6d;
        --danger-strong: #ff3347;
        --shadow: 0 24px 80px rgb(0 0 0 / 0.55);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at 20% 10%, rgb(124 156 255 / 0.2), transparent 34rem),
          radial-gradient(circle at 90% 20%, rgb(255 95 109 / 0.12), transparent 28rem),
          var(--bg);
      }

      .skip-link {
        position: absolute;
        inset-block-start: 1rem;
        inset-inline-start: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: #07101f;
        background: #ffffff;
        font-weight: 700;
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: clamp(1rem, 4vw, 3rem);
      }

      .page-shell {
        display: grid;
        width: min(100%, 58rem);
        gap: 1.25rem;
      }

      .preview-card {
        width: 100%;
        overflow: hidden;
        border: 1px solid rgb(255 255 255 / 0.1);
        border-radius: 2rem;
        background: linear-gradient(145deg, rgb(18 24 39 / 0.92), rgb(11 16 27 / 0.94));
        box-shadow: var(--shadow);
      }

      .hero-image {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 9;
        object-fit: cover;
        background: #151c2d;
      }

      .content {
        display: grid;
        gap: 1.25rem;
        padding: clamp(1.25rem, 4vw, 2rem);
      }

      .eyebrow {
        margin: 0;
        color: var(--accent);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        margin-block: 0;
      }

      h1 {
        font-size: clamp(2rem, 5vw, 3.75rem);
        line-height: 1;
        letter-spacing: -0.06em;
      }

      .description {
        max-width: 58ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .metadata {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        padding: 0;
        margin: 0;
        list-style: none;
      }

      .metadata li {
        border: 1px solid var(--line);
        border-radius: 999px;
        padding: 0.5rem 0.75rem;
        color: var(--muted);
        background: rgb(255 255 255 / 0.04);
        font-size: 0.93rem;
      }

      .actions {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        border-top: 1px solid var(--line);
        padding-top: 1.25rem;
      }

      .status {
        min-height: 1.5rem;
        color: #d7ffdf;
        font-weight: 700;
      }

      .deleted-state {
        border: 1px solid rgb(215 255 223 / 0.28);
        border-radius: 1.5rem;
        padding: clamp(1.25rem, 4vw, 2rem);
        color: #d7ffdf;
        background: rgb(22 163 74 / 0.12);
        box-shadow: var(--shadow);
      }

      button {
        min-width: 44px;
        min-height: 44px;
        border: 0;
        border-radius: 999px;
        padding: 0.8rem 1.05rem;
        color: var(--text);
        background: var(--panel-strong);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.08);
      }

      button:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid #ffffff;
        outline-offset: 4px;
      }

      .trigger,
      .confirm-delete {
        background: linear-gradient(135deg, var(--danger), var(--danger-strong));
        color: #ffffff;
      }

      .secondary {
        border: 1px solid var(--line);
        background: rgb(255 255 255 / 0.08);
      }

      dialog {
        width: min(92vw, 30rem);
        max-height: min(38rem, 90vh);
        overflow: auto;
        border: 1px solid rgb(255 255 255 / 0.14);
        border-radius: 1.5rem;
        padding: 0;
        color: var(--text);
        background: linear-gradient(160deg, #192235, #0d1320);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgb(4 7 13 / 0.78);
        backdrop-filter: blur(0.35rem);
      }

      .dialog-content {
        display: grid;
        gap: 1rem;
        padding: clamp(1.25rem, 5vw, 1.75rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border-radius: 50%;
        color: #ffffff;
        background: rgb(255 95 109 / 0.22);
        font-size: 1.35rem;
      }

      .dialog-content h2 {
        font-size: clamp(1.5rem, 5vw, 2rem);
        line-height: 1.1;
      }

      .dialog-content p {
        color: var(--muted);
        line-height: 1.65;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 0.25rem;
      }

      @media (max-width: 36rem) {
        .actions,
        .dialog-actions {
          align-items: stretch;
          flex-direction: column;
        }

        button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: no-preference) {
        .preview-card,
        dialog {
          animation: rise 420ms ease both;
        }

        @keyframes rise {
          from {
            opacity: 0;
            transform: translateY(0.75rem);
          }

          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
      }

      @media (forced-colors: active) {
        .preview-card,
        .metadata li,
        dialog,
        button {
          border: 1px solid CanvasText;
        }

        button {
          forced-color-adjust: auto;
        }
      }
    </style>
  </head>
